#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn trim_pattern_identity_catalog_is_complete_ordered_and_unique() {
        assert_eq!(VANILLA_TRIM_PATTERN_IDENTITIES.len(), 18);
        let mut resources = HashSet::new();
        for (index, (resource_id, pattern)) in VANILLA_TRIM_PATTERN_IDENTITIES.iter().enumerate() {
            assert_eq!(pattern.vanilla_registry_index(), index);
            assert!(resources.insert(*resource_id));
            assert!(resource_id.starts_with("minecraft:"));
        }
    }

    #[test]
    fn trim_pattern_identity_catalog_preserves_vanilla_mappings() {
        assert_eq!(
            VanillaTrimPatternIdentity::for_vanilla_registry_id(0),
            Some(VanillaTrimPatternIdentity::Sentry)
        );
        assert_eq!(
            VanillaTrimPatternIdentity::for_vanilla_registry_id(17),
            Some(VanillaTrimPatternIdentity::Bolt)
        );
        assert_eq!(
            VanillaTrimPatternIdentity::for_vanilla_registry_id(-1),
            None
        );
        assert_eq!(
            VanillaTrimPatternIdentity::for_vanilla_registry_id(18),
            None
        );
        assert_eq!(
            VanillaTrimPatternIdentity::for_resource_id("minecraft:silence"),
            Some(VanillaTrimPatternIdentity::Silence)
        );
        assert_eq!(
            VanillaTrimPatternIdentity::for_resource_id("example:custom_trim"),
            None
        );
        assert_eq!(
            VanillaTrimPatternIdentity::Bolt.resource_id(),
            "minecraft:bolt"
        );
    }

    #[test]
    fn production_sources_do_not_redeclare_trim_pattern_identity_facts() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/trim_patterns.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                if source.contains("enum VanillaTrimPatternIdentity")
                    || source.contains("const VANILLA_TRIM_PATTERN_KEYS")
                    || source.contains("fn vanilla_trim_pattern_resource_id(")
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel trim-pattern identity owners: {violations:?}"
        );
    }
}
